def f(text: str) -> str:
    """Returns the string after removing the first lowercase alphabetic prefix before a hyphen (if present) or the first lowercase alphabetic prefix (if no hyphen exists)."""
    if '-' in text:
        prefix, suffix = text.split('-', 1)
        if prefix.islower() and prefix.isalpha():
            return suffix
    stripped = text.lstrip('abcdefghijklmnopqrstuvwxyz')
    return stripped if stripped else text
